def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    frame_cells = set()
    # Locate each outlined rectangle as its own connected component, so stray
    # markers of the same color do not enlarge its bounding box.
    for sr in range(h):
        for sc in range(w):
            color = grid[sr][sc]
            if color == 0 or (sr, sc) in seen:
                continue
            q = deque([(sr, sc)])
            seen.add((sr, sc))
            comp = set()
            while q:
                r, c = q.popleft(); comp.add((r, c))
                for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            r0 = min(r for r, _ in comp); r1 = max(r for r, _ in comp)
            c0 = min(c for _, c in comp); c1 = max(c for _, c in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
                         if r in (r0,r1) or c in (c0,c1)}
            if comp == perimeter:
                frames.append((color,r0,r1,c0,c1))
                frame_cells |= comp

