                     if grid[r][c] != 0 and (r,c) not in frame_cells)
    out = [[0]*w for _ in range(h)]
    for color,r0,r1,c0,c1 in frames:
        for r,c in frame_cells:
            if grid[r][c] == color and r0 <= r <= r1 and c0 <= c <= c1:
                out[r][c] = color
        interior = [(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1)]
        # The marker color is indicated by how many isolated copies occur:
        # a checkerboard parity class has either floor or ceil(area/2) cells.
        parity_counts = [sum((r-r0-1+c-c0-1) % 2 == p for r,c in interior) for p in (0,1)]
